mapper.select:
SELECT s.project_sq FROM TBL_SCRAP_S s JOIN TBL_PROJECT_M p ON s.project_sq = p.project_sq WHERE s.user_sq = #{userSq} AND s.scrap_type_cd = 601
AND ( LOWER(p.project_ttl) LIKE CONCAT('%', LOWER(#{searchKeyword}), '%') OR EXISTS ( SELECT 1 FROM TBL_COMPANY_S c WHERE c.company_sq = p.company_sq AND LOWER(c.company_nm) LIKE CONCAT('%', LOWER(#{searchKeyword}), '%') ) ) AND LOWER(p.project_ttl) LIKE CONCAT('%', LOWER(#{searchKeyword}), '%') AND EXISTS ( SELECT 1 FROM TBL_COMPANY_S c WHERE c.company_sq = p.company_sq AND LOWER(c.company_nm) LIKE CONCAT('%', LOWER(#{searchKeyword}), '%') )
ORDER BY p.project_created_at_dtm DESC LIMIT #{limit} OFFSET #{offset}
